Here's a C# code example that connects to Google Translate API and translates text:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Collections.Generic;

class GoogleTranslator
{
    private static readonly HttpClient client = new HttpClient();
    private const string API_KEY = "YOUR_GOOGLE_API_KEY"; // Replace with your actual API key
    private const string BASE_URL = "https://translation.googleapis.com/language/translate/v2";

    public static async Task Main(string[] args)
    {
        try
        {
            // Example usage
            string textToTranslate = "Hello, how are you?";
            string sourceLanguage = "en"; // English
            string targetLanguage = "es"; // Spanish

            string translatedText = await TranslateText(textToTranslate, sourceLanguage, targetLanguage);

            Console.WriteLine($"Original text: {textToTranslate}");
            Console.WriteLine($"Translated text: {translatedText}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    public static async Task<string> TranslateText(string text, string sourceLanguage, string targetLanguage)
    {
        var requestUrl = $"{BASE_URL}?key={API_KEY}";

        var requestBody = new
        {
            q = text,
            source = sourceLanguage,
            target = targetLanguage,
            format = "text"
        };

        var json = JsonConvert.SerializeObject(requestBody);
        var content = new StringContent(json, System.Text.Encoding.UTF8, "application/json");

        var response = await client.PostAsync(requestUrl, content);

        if (response.IsSuccessStatusCode)
        {
            var responseContent = await response.Content.ReadAsStringAsync();
            var translationResponse = JsonConvert.DeserializeObject<TranslationResponse>(responseContent);

            if (translationResponse?.Data?.Translations?.Count > 0)
            {
                return translationResponse.Data.Translations[0].TranslatedText;
            }
        }
        else
        {
            throw new Exception($"Translation failed with status code: {response.StatusCode}");
        }

        return string.Empty;
    }
}

// Response classes for deserialization
public class TranslationResponse
{
    [JsonProperty("data")]
    public TranslationData Data { get; set; }
}

public class TranslationData
{
    [JsonProperty("translations")]
    public List<Translation> Translations { get; set; }
}

public class Translation
{
    [JsonProperty("translatedText")]
    public string TranslatedText { get; set; }
}
```

To use this code, you'll need to:

1. **Install required NuGet packages**:
   ```
   Install-Package Newtonsoft.Json
   ```

2. **Get a Google Cloud API key**:
   - Go to the Google Cloud Console
   - Create a new project or select an existing one
   - Enable the Google Cloud Translation API
   - Create credentials (API key)
   - Replace `YOUR_GOOGLE_API_KEY` in the code with your actual API key

3. **Alternative: Using Google.Cloud.Translation.V2 NuGet package** (recommended):

```csharp
using System;
using Google.Cloud.Translation.V2;

class GoogleTranslatorSimple
{
    public static void Main(string[] args)
    {
        // Set your API key
        Environment.SetEnvironmentVariable("GOOGLE_APPLICATION_CREDENTIALS", "path/to/your/credentials.json");

        // Or use API key directly
        var client = TranslationClient.CreateFromApiKey("YOUR_API_KEY");

        string textToTranslate = "Hello, how are you?";

        // Translate from English to Spanish
        var response = client.TranslateText(textToTranslate, "es", "en");

        Console.WriteLine($"Original: {textToTranslate}");
        Console.WriteLine($"Translation: {response.TranslatedText}");
        Console.WriteLine($"Detected source language: {response.DetectedSourceLanguage}");
    }
}
```

