    def maxDiff(self, num: int) -> int:
        str_num = str(num)
        for c in str_num:
            if c != '9':
                max_str = str_num.replace(c, '9')
                break
            else:
                max_str = str_num

        if str_num[0] != '1':
            min_str = str_num.replace(str_num[0],'1')
        else:
            found = False
            for c in str_num[1:]:
                if c != '0' and c != '1':
                    min_str = str_num.replace(c, '0')
                    found = True
                    break
            if not found:
                min_str = str_num

        return int(max_str) - int(min_str)

