  void _updateFilter(String option, bool selected) {
    setState(() {
      if (option == 'All') {
        _selectedFilterOptions.forEach((key, value) {
          _selectedFilterOptions[key] = selected;
        });
      } else {
        _selectedFilterOptions[option] = selected;
        if (!selected && _selectedFilterOptions['All']!) {
          _selectedFilterOptions['All'] = false;
        }
        if (selected &&
            _selectedFilterOptions.entries
                    .where((e) => e.key != 'All' && e.value)
                    .length ==
                _filterOptions.length - 1) {
          _selectedFilterOptions['All'] = true;
        }
      }
    });
  }

